# ==============================================================================# 022_AUTH_ENGINE.py# ==============================================================================import sqlite3import hashlibfrom pathlib import PathROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")def login(username, password):    password_hash = hashlib.sha256(        password.encode()    ).hexdigest()    cur.execute("""        SELECT *        FROM users        WHERE username=?          AND password_hash=?          AND status='ACTIVE'    """, (        username,        password_hash    ))    user = cur.fetchone()    if user:        return {            "authenticated": True,            "user": dict(user)        }    return {        "authenticated": False    }resultado = login(    "admin",    "iotec123")print("=" * 80)print("AUTH ENGINE")print("=" * 80)print(resultado)print("=" * 80)conn.close()

